// -------------------------------------------------------------
//  LUFTTEMPERATUR: NEGATIV & POSITIV
// -------------------------------------------------------------
function decodeAussenTemp(d24, d25) {
    // NEGATIVE Werte → Data24 = 255 => signed byte
    if (d24 === 255) {
        return (d25 - 256) / 10;
    }

    // POSITIVE Werte → normales WORD
    return (d24 * 256 + d25) / 10;
}

// -------------------------------------------------------------
//  WASSERTEMPERATUR
// -------------------------------------------------------------
function decodeWasserTemp(b1, b2) {
    return (b1 * 256 + b2) / 10;
}

// -------------------------------------------------------------
//  OPTION A: HARTE MIN/MAX-GRENZEN
// -------------------------------------------------------------
function clampAussenTemp(wert) {
    // Luft physikalisch sinnvoll: –30 bis +50
    if (wert < -30) return null;
    if (wert > 50) return null;
    return wert;
}

function clampWasserTemp(wert) {
    // Wasser physikalisch sinnvoll: –5 bis +45
    if (wert < -5) return null;
    if (wert > 45) return null;
    return wert;
}

// -------------------------------------------------------------
//  HELPER FÜR BITAUSWERTUNG
// -------------------------------------------------------------
function bitIstGesetzt(wert, bit) {
    return ((wert >> bit) & 1) === 1;
}

